"""Импорт банковских выписок.

Поддерживаются форматы (кодировка utf-8 с BOM или без, либо cp1251):

    nova         date,amount,description            2026-03-01,-350.00,Кофейня Зерно
    sfera        Дата;Сумма;Описание                01.03.2026;-1 200,50;Магазин Лента
    sfera_split  Дата;Описание;Приход;Расход        01.03.2026;Магазин Лента;;1 200,50

Дубль — транзакция с той же датой, суммой и описанием (после normalize_description),
уже лежащая в хранилище. Если в файле несколько одинаковых строк, каждая «гасит»
по одной такой записи в хранилище: две одинаковые покупки в одном файле остаются
двумя, а повторный импорт того же файла ничего не добавляет.
"""

from __future__ import annotations

import csv
import datetime as dt
import io
import logging
import os
import re
from collections import Counter
from dataclasses import dataclass
from decimal import Decimal

from ledger.clock import Clock, SystemClock
from ledger.errors import (
    StatementError,
    StatementRowError,
    UnknownFormatError,
    ValidationError,
)
from ledger.models import Transaction, parse_amount
from ledger.rules import Categorizer, normalize_text
from ledger.storage import MemoryStore

logger = logging.getLogger(__name__)

NOVA_COLUMNS = ("date", "amount", "description")

# формат -> (разделитель, обязательные колонки заголовка в нижнем регистре)
_FORMATS: dict[str, tuple[str, tuple[str, ...]]] = {
    "nova": (",", NOVA_COLUMNS),
    "sfera": (";", ("дата", "сумма", "описание")),
    "sfera_split": (";", ("дата", "описание", "приход", "расход")),
}

_SPACES = "   "
_SFERA_AMOUNT = re.compile(rf"^(\d+|\d{{1,3}}(?:[{_SPACES}]\d{{3}})+)(,\d+)?$")
_SFERA_DATE = re.compile(r"^\d{2}\.\d{2}\.\d{4}$")


@dataclass(frozen=True)
class RowError:
    line_no: int
    message: str


@dataclass(frozen=True)
class ImportResult:
    format: str
    encoding: str
    added: int
    duplicates: int
    errors: list[RowError]


def normalize_description(text: str) -> str:
    """Вид описания для сравнения (то же, что normalize_text в rules)."""
    return normalize_text(text)


def _decode(data: bytes) -> tuple[str, str]:
    try:
        return data.decode("utf-8-sig"), "utf-8"
    except UnicodeDecodeError:
        pass
    try:
        return data.decode("cp1251"), "cp1251"
    except UnicodeDecodeError as exc:
        raise StatementError(f"cannot decode file: {exc}") from exc


def _reader(text: str, delimiter: str):
    return csv.reader(io.StringIO(text, newline=""), delimiter=delimiter)


def _header_matches(text: str, fmt: str) -> bool:
    delimiter, required = _FORMATS[fmt]
    try:
        header = next(_reader(text, delimiter), None)
    except csv.Error:
        return False
    if not header:
        return False
    names = {cell.strip().casefold() for cell in header}
    return all(col in names for col in required)


def _detect(text: str, fmt: str | None) -> str:
    if fmt is not None:
        if fmt not in _FORMATS:
            raise UnknownFormatError(f"unknown format {fmt!r}")
        if not _header_matches(text, fmt):
            raise UnknownFormatError(f"header does not match format {fmt!r}", line_no=1)
        return fmt
    for name in _FORMATS:
        if _header_matches(text, name):
            return name
    raise UnknownFormatError("unrecognized statement header", line_no=1)


def _read_file(path: str | os.PathLike[str]) -> tuple[str, str]:
    with open(path, "rb") as fh:
        return _decode(fh.read())


def detect_format(path: str | os.PathLike[str]) -> str:
    """Определяет формат выписки по заголовку; иначе UnknownFormatError."""
    text, _ = _read_file(path)
    return _detect(text, None)


def _parse_date(cell: str, fmt: str) -> dt.date:
    value = cell.strip()
    try:
        if fmt == "nova":
            return dt.date.fromisoformat(value)
        if not _SFERA_DATE.match(value):
            raise ValueError(value)
        return dt.datetime.strptime(value, "%d.%m.%Y").date()
    except ValueError:
        raise ValidationError(f"invalid date {cell!r}") from None


def _parse_sfera_amount(cell: str, *, signed: bool) -> Decimal:
    """Сумма вида '-1 200,50'; знак допустим только при signed=True."""
    value = cell.strip().replace("−", "-")
    sign = ""
    if value[:1] in ("+", "-"):
        if not signed:
            raise ValidationError(f"unexpected sign in amount {cell!r}")
        sign, value = value[0], value[1:].lstrip(_SPACES)
    if not _SFERA_AMOUNT.match(value):
        raise ValidationError(f"invalid amount: {cell!r}")
    for ch in _SPACES:
        value = value.replace(ch, "")
    amount = parse_amount(value.replace(",", "."))
    return -amount if sign == "-" else amount


def _build(fmt: str, cells: dict[str, str], imported_at: dt.datetime) -> Transaction:
    if fmt == "nova":
        date = _parse_date(cells["date"], fmt)
        amount = parse_amount(cells["amount"])
        description = cells["description"]
    else:
        date = _parse_date(cells["дата"], fmt)
        description = cells["описание"]
        if fmt == "sfera":
            amount = _parse_sfera_amount(cells["сумма"], signed=True)
        else:
            income, expense = cells["приход"].strip(), cells["расход"].strip()
            if bool(income) == bool(expense):
                raise ValidationError("exactly one of income/expense must be filled")
            if income:
                amount = _parse_sfera_amount(income, signed=False)
            else:
                amount = -_parse_sfera_amount(expense, signed=False)
    return Transaction(
        date=date, amount=amount, description=description.strip(), imported_at=imported_at
    )


def _key(tx: Transaction) -> tuple:
    return (tx.date, tx.amount, normalize_description(tx.description))


def import_statement(
    path: str | os.PathLike[str],
    store: MemoryStore,
    *,
    fmt: str | None = None,
    strict: bool = False,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> ImportResult:
    """Импортирует выписку в store; формат определяется по заголовку, если fmt не задан.

    Все новые транзакции пишутся в хранилище одной пачкой после полного разбора файла,
    поэтому при ошибке (в том числе в strict-режиме) в хранилище не попадает ничего.
    """
    text, encoding = _read_file(path)
    fmt = _detect(text, fmt)
    delimiter, required = _FORMATS[fmt]
    clock = clock or SystemClock()
    imported_at = clock.now()

    reader = _reader(text, delimiter)
    header = next(reader)
    index: dict[str, int] = {}
    for i, cell in enumerate(header):
        index.setdefault(cell.strip().casefold(), i)
    width = max(index[c] for c in required) + 1

    existing = Counter(_key(tx) for tx in store.all())
    new: list[Transaction] = []
    errors: list[RowError] = []
    duplicates = 0

    prev_line = reader.line_num
    while True:
        try:
            row = next(reader)
        except StopIteration:
            break
        except csv.Error as exc:
            line_no, prev_line = prev_line + 1, max(reader.line_num, prev_line + 1)
            if strict:
                raise StatementRowError(str(exc), line_no=line_no) from exc
            errors.append(RowError(line_no, str(exc)))
            continue
        line_no, prev_line = prev_line + 1, reader.line_num
        if all(not cell.strip() for cell in row):
            continue
        try:
            if len(row) < width:
                raise ValidationError("not enough fields")
            tx = _build(fmt, {c: row[index[c]] for c in required}, imported_at)
        except ValidationError as exc:
            if strict:
                raise StatementRowError(str(exc), line_no=line_no) from exc
            errors.append(RowError(line_no, str(exc)))
            continue
        key = _key(tx)
        if existing[key] > 0:
            existing[key] -= 1
            duplicates += 1
            continue
        if categorizer is not None:
            category = categorizer.categorize(tx)
            if category is not None:
                tx = Transaction(
                    date=tx.date,
                    amount=tx.amount,
                    description=tx.description,
                    category=category,
                    imported_at=tx.imported_at,
                )
        new.append(tx)

    if new:
        store.add_many(new)
    logger.info(
        "imported %d transactions from %s (%d duplicates, %d errors)",
        len(new), path, duplicates, len(errors),
    )
    return ImportResult(fmt, encoding, len(new), duplicates, errors)


def import_csv(
    path: str | os.PathLike[str],
    store: MemoryStore,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> int:
    """Совместимая обёртка: строгий импорт, возвращает число добавленных транзакций."""
    result = import_statement(path, store, strict=True, categorizer=categorizer, clock=clock)
    return result.added

